function isInterleave(s1: string, s2: string, s3: string): boolean {
  const m = s1.length;
  const n = s2.length;
  // Длины должны сойтись — иначе часть символов лишняя или не хватает
  if (m + n !== s3.length) return false;

  // dp[j] — можно ли из первых i символов s1 и первых j символов s2
  // составить первые i + j символов s3 (строка i таблицы, сжатая в одномерный массив)
  const dp: boolean[] = new Array(n + 1).fill(false);

  for (let i = 0; i <= m; i++) {
    for (let j = 0; j <= n; j++) {
      if (i === 0 && j === 0) {
        // Пустые префиксы дают пустую строку
        dp[j] = true;
        continue;
      }
      // Очередной символ s3 имеет индекс i + j - 1
      const c = s3[i + j - 1];
      // Вариант 1: последний символ взят из s1 — смотрим dp[i - 1][j],
      // это старое значение dp[j] (ещё не перезаписано в строке i)
      const fromS1 = i > 0 && dp[j] && s1[i - 1] === c;
      // Вариант 2: последний символ взят из s2 — смотрим dp[i][j - 1],
      // это уже обновлённое значение dp[j - 1]
      const fromS2 = j > 0 && dp[j - 1] && s2[j - 1] === c;
      dp[j] = fromS1 || fromS2;
    }
  }

  return dp[n];
}

// Время: O(m · n)
// Память: O(n) — одна строка таблицы, как просит follow-up
